+'use server';
+
+import { revalidatePath } from 'next/cache';
+
+import prisma from '@/lib/prisma';
+import { currentUser } from '@/lib/auth';
+import { checkCurrentUserPermission } from '@/data/admin/permissions';
+import createLogger from '@/lib/logger';
+
+const logger = createLogger('admin-coin-pool-actions');
+
+/**
+ * 將現有用戶設為代幣池管理員：新增 coin-pool-admin 角色並建立 CoinPoolAccess
+ */
+export async function addUserAsCoinPoolAdmin(
+  existingUserId: string,
+  businessAdminUserId: string
+): Promise<{ success?: string; error?: string }> {
+  const hasPermission = await checkCurrentUserPermission('write-coinpools');
+  if (!hasPermission) {
+    return { error: 'admin.permissions.noPermission' };
+  }
+
+  const currentUserData = await currentUser();
+  if (!currentUserData?.id) {
+    return { error: 'common.error.unauthorized' };
+  }
+
+  const user = await prisma.user.findUnique({
+    where: { id: existingUserId },
+    select: {
+      id: true,
+      userAdminRoles: {
+        select: {
+          adminRole: { select: { name: true } }
+        }
+      }
+    }
+  });
+
+  if (!user) {
+    return { error: 'User not found' };
+  }
+
+  const isAlreadyCoinPoolAdmin = user.userAdminRoles.some(
+    (ur) => ur.adminRole.name === 'coin-pool-admin'
+  );
+  if (isAlreadyCoinPoolAdmin) {
+    return { error: 'User is already a coin pool admin' };
+  }
+
+  const businessAdmin = await prisma.user.findUnique({
+    where: { id: businessAdminUserId },
+    select: {
+      id: true,
+      userAdminRoles: {
+        select: { adminRole: { select: { name: true } } }
+      }
+    }
+  });
+
+  if (!businessAdmin) {
+    return { error: 'Business admin not found' };
+  }
+
+  const isBusinessAdmin = businessAdmin.userAdminRoles.some(
+    (ur) => ur.adminRole.name === 'business-admin'
+  );
+  if (!isBusinessAdmin) {
+    return { error: 'Selected user is not a business admin' };
+  }
+
+  const coinPoolAdminRole = await prisma.adminRole.findUnique({
+    where: { name: 'coin-pool-admin' },
+    select: { id: true }
+  });
+
+  if (!coinPoolAdminRole) {
+    logger.error('coin-pool-admin role not found');
+    return { error: 'Role not found' };
+  }
+
+  try {
+    await prisma.$transaction(async (tx) => {
+      await tx.userAdminRole.create({
+        data: {
+          userId: existingUserId,
+          adminRoleId: coinPoolAdminRole.id
+        }
+      });
+      await tx.coinPoolAccess.create({
+        data: {
+          coinPoolId: existingUserId,
+          userId: businessAdminUserId,
+          updateBy: currentUserData.id
+        }
+      });
+    });
+
+    revalidatePath('/admin/coin-pools');
+    revalidatePath('/admin/users');
+
+    return { success: 'Coin pool admin assigned successfully' };
+  } catch (err) {
+    logger.error(
+      'addUserAsCoinPoolAdmin error',
+      err instanceof Error ? err : { cause: err }
+    );
+    return { error: 'common.error.unknown' };
+  }
+}
