+const UpdateAiToolVisibilitySchema = z.object({
+  id: z.string().cuid(),
+  isPublic: z.boolean()
+});
+
+/**
+ * 僅更新 AI 工具的公開狀態（不觸發完整表單驗證）
+ * 權限：系統管理員或工具擁有者
+ */
+export async function updateAiToolVisibility(
+  data: z.infer<typeof UpdateAiToolVisibilitySchema>
+): Promise<{ success: boolean; error?: string }> {
+  try {
+    const user = await currentUser();
+    if (!user) {
+      return { success: false, error: 'LOGIN_REQUIRED' };
+    }
+
+    const { id, isPublic } = UpdateAiToolVisibilitySchema.parse(data);
+
+    const isSystemAdmin = await checkIsSystemAdmin();
+    if (!isSystemAdmin) {
+      const tool = await prisma.aiTool.findUnique({
+        where: { id },
+        select: { createdBy: true }
+      });
+      if (!tool) {
+        return { success: false, error: 'AI_TOOL_NOT_FOUND' };
+      }
+      if (tool.createdBy !== user.id) {
+        return { success: false, error: 'AI_TOOL_NO_ACCESS' };
+      }
+    }
+
+    await prisma.aiTool.update({
+      where: { id },
+      data: {
+        isPublic,
+        updatedBy: user.id
+      }
+    });
+
+    revalidatePath('/api/ai-tools');
+    revalidatePath('/admin/ai-tools');
+    revalidatePath(`/admin/ai-tools/${id}/edit`);
+
+    return { success: true };
+  } catch (error) {
+    if (error instanceof z.ZodError) {
+      return {
+        success: false,
+        error: error.errors.map((e) => e.message).join(', ')
+      };
+    }
+    logger.error(
+      '更新 AI 工具公開狀態失敗',
+      error instanceof Error ? error : { cause: String(error) }
+    );
+    return {
+      success: false,
+      error: ERROR_IDS.AI_TOOL_UPDATE_FAILED
+    };
+  }
+}
