+
+export function AiToolGenerationTrendChart({
+  data,
+  isLoading
+}: AiToolGenerationTrendChartProps) {
+  const t = useTranslations('admin.aiTools.report');
+  const tCommon = useTranslations('common');
+
+  const chartData = useMemo(() => {
+    return data.map((d) => ({
