--- /dev/null
+++ b/app/[locale]/(main)/admin/ai-tools/report/_components/ai-tool-summary-cards.tsx
@@ -0,0 +1,140 @@
+'use client';
+
+import { useTranslations } from 'next-intl';
+
+import { Card, CardContent } from '@/components/ui/card';
+import { cn } from '@/lib/utils';
+import { calculateChange } from '@/utils/stats';
+import type { AiToolStatsSummary } from '@/data/ai-tool-stats';
+
+interface AiToolSummaryCardsProps {
+  summary: AiToolStatsSummary;
+  isLoading?: boolean;
+  previousSummary?: AiToolStatsSummary | null;
+  isPreviousLoading?: boolean;
+}
+
+const statItems = [
+  { key: 'totalUsers' as const },
+  { key: 'totalImages' as const },
+  { key: 'totalVideos' as const },
+  { key: 'toolsUsedCount' as const },
+  { key: 'unusedToolsCount' as const },
+  { key: 'aiToolShareOfTotal' as const }
+] as const;
+
+export function AiToolSummaryCards({
+  summary,
+  isLoading,
+  previousSummary,
+  isPreviousLoading
+}: AiToolSummaryCardsProps) {
+  const t = useTranslations('admin.aiTools.report');
+
+  const values: (number | null)[] = [
+    summary.uniqueUserCount,
+    summary.totalImageCount,
+    summary.totalVideoCount,
+    summary.toolsUsedCount,
+    summary.unusedToolsCount,
+    summary.aiToolShareOfTotal ?? null
+  ];
+
+  const previousValues = previousSummary
+    ? [
+        previousSummary.uniqueUserCount,
+        previousSummary.totalImageCount,
+        previousSummary.totalVideoCount,
+        previousSummary.toolsUsedCount,
+        previousSummary.unusedToolsCount,
+        previousSummary.aiToolShareOfTotal ?? null
+      ]
+    : [undefined, undefined, undefined, undefined, undefined, undefined];
+
+  if (isLoading) {
+    return (
+      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4">
+        {[1, 2, 3, 4, 5, 6].map((i) => (
+          <Card key={i} className="border shadow-sm">
+            <CardContent className="p-4 flex items-center justify-between text-center gap-1">
+              <div className="h-3 w-20 bg-muted rounded mb-2 animate-pulse" />
+              <div className="h-8 w-16 bg-muted rounded animate-pulse" />
+            </CardContent>
+          </Card>
+        ))}
+      </div>
+    );
+  }
+
+  return (
+    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4">
+      {statItems.map((item, index) => {
+        const value = values[index];
+        const previousValue = previousValues[index];
+        const change =
+          previousValue !== undefined &&
+          value !== null &&
+          !isPreviousLoading
+            ? calculateChange(value as number, previousValue as number)
+            : null;
+        const isPositive = change !== null && change > 0;
+        const isNegative = change !== null && change < 0;
+        const isPercent = item.key === 'aiToolShareOfTotal';
+
+        return (
+          <Card
+            key={item.key}
+            className="border shadow-sm hover:shadow-md transition-all"
+          >
+            <CardContent className="p-4">
+              <div className="flex items-center justify-center mb-2">
+                <p className="text-xs text-muted-foreground text-center">
+                  {t(item.key)}
+                </p>
+              </div>
+              <p className="flex items-center justify-center gap-1 text-lg md:text-2xl font-bold text-center">
+                {value === null
+                  ? '—'
+                  : isPercent
+                    ? `${(value as number).toFixed(1)}%`
+                    : typeof value === 'number' && value % 1 !== 0
+                      ? value.toFixed(2)
+                      : (value as number).toLocaleString()}
+              </p>
+              <div className="flex items-center justify-center gap-1 mt-1">
+                {previousValue !== undefined && !isPreviousLoading && (
+                  <p className="text-xs text-muted-foreground text-center">
+                    {t('previousPeriod', { defaultMessage: '前一期' })}:{' '}
+                    {previousValue === null
+                      ? '—'
+                      : isPercent
+                        ? `${(previousValue as number).toFixed(1)}%`
+                        : typeof previousValue === 'number' &&
+                            previousValue % 1 !== 0
+                          ? (previousValue as number).toFixed(2)
+                          : (previousValue as number).toLocaleString()}
+                  </p>
+                )}
+                {change !== null && !isPreviousLoading && (
+                  <div
+                    className={cn(
+                      'flex items-center gap-1 text-xs font-medium',
+                      isPositive && 'text-emerald-600 dark:text-emerald-400',
+                      isNegative && 'text-red-600 dark:text-red-400',
+                      !isPositive && !isNegative && 'text-muted-foreground'
+                    )}
+                  >
+                    <span>
+                      {change > 0 ? '+' : ''}
+                      {change.toFixed(1)}%
+                    </span>
+                  </div>
+                )}
+              </div>
+            </CardContent>
+          </Card>
+        );
+      })}
+    </div>
+  );
+}
