+'use client';
+
+import { useTranslations } from 'next-intl';
+import type { DateRange } from 'react-day-picker';
+import { Button } from '@/components/ui/button';
+import { FilterAndSearch } from '@/components/admin/filter-and-search';
+import { UserSelector } from '@/components/admin/user-selector';
+import { InvitationCodeSelector } from '@/components/admin/invitation-code-selector';
+import { DateRangePicker } from '@/components/ui/date-range-picker';
+import {
+  type DateRangeType,
+  getDefaultDateRange
+} from '@/utils/stats';
+
+export interface AiToolsReportFiltersProps {
+  dateRangeType: DateRangeType;
+  onDateRangeTypeChange: (type: DateRangeType) => void;
+  selectedDateRange: DateRange | undefined;
+  onSelectedDateRangeChange: (range: DateRange | undefined) => void;
+  userIds: string[];
+  onUserIdsChange: (value: string[]) => void;
+  invitationCodeIds: string[];
+  onInvitationCodeIdsChange: (value: string[]) => void;
+}
+
+export function AiToolsReportFilters({
+  dateRangeType,
+  onDateRangeTypeChange,
+  selectedDateRange,
+  onSelectedDateRangeChange,
+  userIds,
+  onUserIdsChange,
+  invitationCodeIds,
+  onInvitationCodeIdsChange
+}: AiToolsReportFiltersProps) {
+  const t = useTranslations('admin.aiTools.report');
+
+  return (
+    <FilterAndSearch>
+      <div className="flex flex-col sm:flex-row sm:flex-wrap gap-3 w-full">
+        <div className="flex gap-2 flex-wrap sm:flex-nowrap">
+          {(
+            ['today', 'yesterday', '7days', '30days'] as DateRangeType[]
+          ).map((type) => (
+            <Button
+              key={`ai-tools-report-button-${type}`}
+              variant={dateRangeType === type ? 'default' : 'outline'}
+              size="sm"
+              onClick={() => onDateRangeTypeChange(type)}
+            >
+              {t(type, {
+                defaultMessage:
+                  type === 'today'
+                    ? '今日'
+                    : type === 'yesterday'
+                      ? '昨日'
+                      : type === '7days'
+                        ? '7天'
+                        : '30天'
+              })}
+            </Button>
+          ))}
+        </div>
+        <div className="flex-1">
+          <DateRangePicker
+            className="w-full flex-col sm:flex-row"
+            date={selectedDateRange || getDefaultDateRange(dateRangeType)}
+            onDateChange={onSelectedDateRangeChange}
+            placeholder={t('selectDateRange', {
+              defaultMessage: '選擇日期範圍'
+            })}
+          />
+        </div>
+        <div className="w-full flex-1 min-w-[160px] max-w-[280px]">
+          <UserSelector
+            value={userIds}
+            onValueChange={(value) => {
+              onUserIdsChange(Array.isArray(value) ? value : []);
+            }}
+            className="w-full"
+            multiple
+            maxDisplayCount={2}
+          />
+        </div>
+        <div className="w-full flex-1 min-w-[180px] max-w-[280px]">
+          <InvitationCodeSelector
+            value={invitationCodeIds}
+            onValueChange={onInvitationCodeIdsChange}
+            className="w-full"
+            maxDisplayCount={2}
+          />
+        </div>
+      </div>
+    </FilterAndSearch>
+  );
+}
