+'use server';
+
+import { OutputType } from '@prisma/client';
+import { Image as ImageIcon, Type, Video } from 'lucide-react';
+import { getTranslations } from 'next-intl/server';
+
+import { cn } from '@/lib/utils';
+
+interface OutputTypeBadgeProps {
+  outputType: OutputType;
+  className?: string;
+}
+
+const OUTPUT_TYPE_CONFIG: Record<
+  OutputType,
+  {
+    Icon: typeof Type;
+    labelKey: 'text' | 'image' | 'video';
+  }
+> = {
+  TEXT: {
+    Icon: Type,
+    labelKey: 'text'
+  },
+  IMAGE: {
+    Icon: ImageIcon,
+    labelKey: 'image'
+  },
+  VIDEO: {
+    Icon: Video,
+    labelKey: 'video'
+  }
+};
+
+const BADGE_BASE_CLASS =
+  'inline-flex items-center whitespace-nowrap rounded-full border border-gray-200 bg-gray-100 px-2.5 py-0.5 text-xs font-medium text-gray-700';
+
+export async function OutputTypeBadge({
+  outputType,
+  className
+}: OutputTypeBadgeProps) {
+  const tCommon = await getTranslations('common');
+  const config = OUTPUT_TYPE_CONFIG[outputType];
+
+  if (!config) {
+    return (
+      <div className={cn(BADGE_BASE_CLASS, className)}>{outputType}</div>
+    );
+  }
+
+  const { Icon, labelKey } = config;
+  const label = tCommon(`terms.${labelKey}`);
+
+  return (
+    <div className={cn(BADGE_BASE_CLASS, className)}>
+      <Icon className="mr-1 h-3 w-3" />
+      <span>{label}</span>
+    </div>
+  );
+}
